package com.vandorlabs.neoforge.copifier;
import com.vandorlabs.neoforge.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;

/** Real sneak-capture and normal apply for vanilla material states, without vanilla tile ownership. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierVanillaChecks {
 private static final BlockPos BASE=new BlockPos(15008,100,14640),TARGET=BASE.east(3);private static int checks;private static volatile Object sink;
 static boolean enabled(){String phase=System.getProperty("vandorlabs.transmitterPhase","");return phase.equals("copifier-vanilla-write")||phase.equals("copifier-vanilla-read");}
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Copifier vanilla: "+why);}
 private static boolean use(ServerPlayer actor,BlockPos pos){return actor.gameMode.useItemOn(actor,actor.serverLevel(),actor.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos).add(0,0,-.5),Direction.NORTH,pos,false)).consumesAction();}
 private static void put(ServerLevel level,BlockPos pos,BlockState state){level.getChunkAt(pos);level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);level.setBlock(pos,state,18);}
 private static void names(ItemStack tool){
  var root=NativeCopifierItem.data(tool);root.putByteArray("RetainedOpaqueToolData",new byte[65536]);tool.set(DataComponents.CUSTOM_DATA,CustomData.of(root));var before=NativeCopifierItem.data(tool);
  var bean=java.lang.management.ManagementFactory.getThreadMXBean();if(!(bean instanceof com.sun.management.ThreadMXBean meter)||!meter.isThreadAllocatedMemorySupported())throw new AssertionError("Allocation meter unavailable");meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId();
  for(int i=0;i<3000;i++){sink=tool.getItem().getName(tool);sink=NativeCopifierItem.data(tool).getString(NativeCopifierClipboard.SOURCE);}long start=meter.getThreadAllocatedBytes(thread);for(int i=0;i<1000;i++)sink=NativeCopifierItem.data(tool).getString(NativeCopifierClipboard.SOURCE);long copied=meter.getThreadAllocatedBytes(thread)-start;start=meter.getThreadAllocatedBytes(thread);for(int i=0;i<1000;i++)sink=tool.getItem().getName(tool);long names=meter.getThreadAllocatedBytes(thread)-start;need(copied>64L*1024*1000&&names<copied/8,"name reads avoid copying opaque clipboard tree");need(before.equals(NativeCopifierItem.data(tool)),"name getter is read-only");System.out.println("[vandorlabs][copifier-vanilla] name-allocation PASS baseline1000="+copied+" new1000="+names);
 }
 private static void write(ServerLevel level){var actor=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new java.util.UUID(0,1876),"VanillaCapture"));actor.setGameMode(GameType.SURVIVAL);actor.setPos(BASE.getX()+.5,BASE.getY()+1,BASE.getZ()-2);var tool=new ItemStack(NativeCopifierItemChecks.ITEM);actor.setItemInHand(InteractionHand.MAIN_HAND,tool);
  var states=new BlockState[]{Blocks.STONE.defaultBlockState(),Blocks.GRANITE.defaultBlockState(),Blocks.CHERRY_LOG.defaultBlockState(),Blocks.CHERRY_LOG.defaultBlockState().setValue(RotatedPillarBlock.AXIS,Direction.Axis.X),Blocks.OAK_LOG.defaultBlockState().setValue(RotatedPillarBlock.AXIS,Direction.Axis.X),Blocks.REDSTONE_LAMP.defaultBlockState().setValue(BlockStateProperties.LIT,true),Blocks.REDSTONE_WIRE.defaultBlockState().setValue(RedStoneWireBlock.POWER,15),Blocks.FURNACE.defaultBlockState().setValue(FurnaceBlock.FACING,Direction.EAST).setValue(BlockStateProperties.LIT,true),Blocks.OAK_DOOR.defaultBlockState().setValue(DoorBlock.FACING,Direction.WEST).setValue(DoorBlock.HALF,DoubleBlockHalf.UPPER),Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7),Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.EAST)};
  for(var desired:states){put(level,BASE,Blocks.AIR.defaultBlockState());put(level,BASE.below(2),Blocks.STONE.defaultBlockState());put(level,BASE.below(),desired.getBlock() instanceof CropBlock?Blocks.FARMLAND.defaultBlockState():desired.getBlock() instanceof DoorBlock?desired.setValue(DoorBlock.HALF,DoubleBlockHalf.LOWER):Blocks.STONE.defaultBlockState());put(level,BASE.west(),desired.getBlock() instanceof RedStoneWireBlock?Blocks.REDSTONE_BLOCK.defaultBlockState():Blocks.AIR.defaultBlockState());put(level,BASE,desired);var state=level.getBlockState(BASE);need(state.getBlock()==desired.getBlock(),"native source fixture remains present: desired="+desired+" actual="+state);var tile=level.getBlockEntity(BASE);if(tile instanceof net.minecraft.world.Container container)container.setItem(0,new ItemStack(Items.DIAMOND,7));var tileBefore=tile==null?null:tile.saveWithFullMetadata(level.registryAccess());actor.setShiftKeyDown(true);need(use(actor,BASE),"actual vanilla capture "+state);var root=NativeCopifierItem.data(tool);var captured=NativeCopifierClipboard.settings(root);int choice=NativeMaterialRegistry.snapshot().stateSamples().get(state);need(captured.size()==4,"four semantic fields only");for(String key:new String[]{"wall_texture","side_texture","glass_material","door_face_texture"})need(captured.getInt(key)==choice,"Source fallback key "+key);need(level.getBlockState(BASE)==state&&(tileBefore==null||tile==level.getBlockEntity(BASE)&&tileBefore.equals(tile.saveWithFullMetadata(level.registryAccess()))),"source block/tile ownership unchanged");put(level,TARGET,VandorLabsBootstrap.PROGRAMMABLE_BLOCK.get().defaultBlockState());actor.setShiftKeyDown(false);need(use(actor,TARGET)&&((ProgrammableBlockEntity)level.getBlockEntity(TARGET)).settings().mainTexture==choice,"actual apply sampled artwork");need(root.equals(NativeCopifierItem.data(tool)),"apply preserves clipboard");need(NativeCopifierUndo.undo(actor)&&((ProgrammableBlockEntity)level.getBlockEntity(TARGET)).settings().mainTexture==0,"sampled artwork undo");}
  for(var state:new BlockState[]{Blocks.AIR.defaultBlockState(),Blocks.WATER.defaultBlockState(),Blocks.LAVA.defaultBlockState(),VandorLabsBootstrap.TRIGGER_BLOCK.get().defaultBlockState()}){put(level,BASE,state);actor.setShiftKeyDown(true);var before=NativeCopifierItem.data(tool);need(!use(actor,BASE)&&before.equals(NativeCopifierItem.data(tool)),"air/liquid/unsupported namespace preserve prior clipboard");}
  var exact=Blocks.OAK_LOG.defaultBlockState().setValue(RotatedPillarBlock.AXIS,Direction.Axis.X);put(level,BASE,exact);need(use(actor,BASE),"saved explicit-state capture");actor.setShiftKeyDown(false);put(level,TARGET,VandorLabsBootstrap.PROGRAMMABLE_BLOCK.get().defaultBlockState());need(use(actor,TARGET),"saved explicit-state apply");names(tool);System.out.println("[vandorlabs][copifier-vanilla] write PASS checks="+checks+" actualCapture/apply/undo/vanillaOwnership/refusals");
 }
 private static void read(ServerLevel level){level.getChunkAt(TARGET);need(level.getBlockEntity(TARGET) instanceof ProgrammableBlockEntity,"saved housing owner");var owner=(ProgrammableBlockEntity)level.getBlockEntity(TARGET);need(owner.settings().mainTexture==0x3c622350,"stable explicit-state value saved");need(NativeMaterialRegistry.snapshot().states().get(owner.settings().mainTexture)==Blocks.OAK_LOG.defaultBlockState().setValue(RotatedPillarBlock.AXIS,Direction.Axis.X),"exact sampled property survives process restart");System.out.println("[vandorlabs][copifier-vanilla] read PASS checks="+checks);}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{if(System.getProperty("vandorlabs.transmitterPhase").endsWith("write"))write(event.getServer().overworld());else read(event.getServer().overworld());event.getServer().saveEverything(true,true,true);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][copifier-vanilla] FAIL "+failure);}finally{event.getServer().halt(false);}}
}
